**Write a sufu program that, given a list of integers, reverses the list and then computes the sum of its elements.**
Inductive List = nil Unit | cons {Int, List};
spec = fix (
    \f: List -> Int. \xs: List. 
    match xs with
      nil _ -> 0
    | cons {h, t} -> + h (f t)
    end
);
snoc = fix (
    \f: List -> Int -> List. \xs: List. \w: Int. 
    match xs with
      nil _ -> cons {w, nil unit}
    | cons {h, t} -> cons {h, f t w}
    end
);

