    | opMinus _ -> tArithUn {aMinus unit, t}
    | opNot _ -> tBoolUn {bNot unit, t}
    | opAnd _ -> tBoolUn {bAnd unit, t}
    | opOr _ -> tBoolUn {bOr unit, t}
